"use strict";(globalThis.webpackChunkmy_website=globalThis.webpackChunkmy_website||[]).push([[9214],{86103(i){i.exports=JSON.parse('{"tag":{"label":"\u97f3\u6a02\u88fd\u4f5c","permalink":"/tags/\u97f3\u6a02\u88fd\u4f5c","allTagsPath":"/tags","count":21,"items":[{"id":"production/keyboard-midi-faq","title":"\u4e00\u4e9b\u95dc\u65bc\u9375\u76e4\u8207MIDI \u7684 FAQ","description":"\u6700\u8fd1\u6709\u670b\u53cb (\u5409\u4ed6\u624b) \u56e0\u70ba\u6559\u5b78\u8ddf\u8868\u6f14\u9700\u8981, \u8cb7\u4e86\u4e00\u53f0 Yamaha PSR-3000 \u4f5c\u70ba\u5de5\u4f5c\u7684\u65b0\u5925\u4f34. \u540c\u6642\u4ed6\u4e5f\u5e0c\u671b\u80fd\u5920\u7528\u9375\u76e4\u672c\u8eab\u7684\u97f3\u6e90\u4f86\u64ad\u653e\u7db2\u8def\u4e0a\u6293\u7684 MIDI \u6a94. \u53e6\u5916\u6a02\u5718\u7684\u9375\u76e4\u624b\u60f3\u628a\u81ea\u5df1\u7684\u9748\u611f\u8a18\u9304\u4e0b\u4f86, \u9032\u800c\u7528 Cubase \u7de8\u66f2. \u4f46\u662f\u90fd\u9047\u5230\u5e7e\u500b\u985e\u4f3c\u7684\u554f\u984c:","permalink":"/production/keyboard-midi-faq"},{"id":"production/violin-performance-basics","title":"\u5c0f\u63d0\u7434\u6f14\u594f\u7684\u57fa\u672c\u7279\u6027","description":"1. \u97f3\u57df\u7bc4\u570d: G3 ~ \u92fc\u7434\u6700\u9ad8\u97f3\u57df (C8)","permalink":"/production/violin-performance-basics"},{"id":"guitar/realistic-midi-programming","title":"\u5982\u4f55\u628a MIDI \u505a\u5f97 \\"\u903c\u771f\\"","description":"\u9019\u662f\u5728\u9109\u6c11\u7ad9 DigitalMusic \u7248\u56de\u7b54\u7248\u53cb\u7684\u6587\u5b57.","permalink":"/guitar/realistic-midi-programming"},{"id":"production/basic-concepts-of-sampling","title":"\u53d6\u6a23\u7684\u57fa\u672c\u6982\u5ff5","description":"\u9019\u662f\u7db2\u53cb\u5728 \u9109\u6c11\u7ad9 Keyboard \u7248\u554f\u7684\u554f\u984c, \u6211\u82b1\u4e86\u4e00\u9ede\u6642\u9593\u56de\u7b54\u57fa\u672c\u7684\u6982\u5ff5.","permalink":"/production/basic-concepts-of-sampling"},{"id":"production/basic-acoustics-and-digital-music-production","title":"\u57fa\u790e\u8072\u5b78\u8207\u6578\u4f4d\u97f3\u6a02\u88fd\u4f5c","description":"\u5c0d\u65bc \\"\u8072\u97f3\\" \u7684\u7269\u7406\u73fe\u8c61\uff0c\u5f88\u591a\u7269\u7406\u5b78\u3001\u97f3\u97ff\u6216 PA \u76f8\u95dc\u7684\u66f8\u90fd\u6703\u63d0\u5230\u4e00\u4e9b\u57fa\u672c\u6982\u5ff5\uff0c\u9019\u4e9b\u6982\u5ff5\u5c0d\u65bc\u97f3\u6a02\u88fd\u4f5c\u4e0a\uff0c\u5c24\u5176\u8981\u505a\u51fa\u6bd4\u8f03\u6709\u8c50\u5bcc\u8072\u97ff\u7684\u97f3\u6a02\uff0c\u57fa\u790e\u7684\u8072\u97f3\u7406\u8ad6\u66f4\u662f\u8981\u6709\u76f8\u7576\u7684\u77ad\u89e3\u3002\\n","permalink":"/production/basic-acoustics-and-digital-music-production"},{"id":"production/soft-or-hard-synth","title":"\u8edf\u7684? \u786c\u7684?","description":"\\"\u97f3\u6e90\\" \u6c7a\u5b9a\u97f3\u6a02\u6210\u54c1\u7684\u8cea\u611f. \u8edf\u9ad4\u97f3\u6e90\u7684\u51fa\u73fe, \u4ed6\u7684\u6548\u679c, \u54c1\u8cea, \u7b49\u5404\u9805\u6578\u64da\u8ddf\u50b3\u7d71\u7684\u786c\u9ad4\u6bd4\u8f03\u8d77\u4f86, \u5e7e\u4e4e\u662f\u4ee5\u6307\u6578\u66f2\u7dda\u7684\u901f\u5ea6\u5728\u6210\u9577. \u6709\u670b\u53cb\u554f\u6211, \u90a3\u786c\u9ad4\u97f3\u6e90\u662f\u4e0d\u662f\u53ef\u4ee5\u6dd8\u6c70\u4e86??","permalink":"/production/soft-or-hard-synth"},{"id":"production/bouncing-tracks-tips","title":"\u904e\u5e36\u6ce8\u610f\u4e8b\u9805","description":"\u985e\u6bd4\u6642\u4ee3\u662f\u7528 Sequencer \u9001 MIDI Message \u7d66\u786c\u9ad4\u97f3\u6e90, \u7136\u5f8c\u5c07\u786c\u9ad4\u97f3\u6e90\u7684\u985e\u6bd4\u8a0a\u865f\u9304 (\u904e) \u5230\u76e4\u5e36. \u9019\u6a23\u7684\u904e\u7a0b\u6700\u5f8c\u88ab\u7a31\u4e4b\u70ba\u904e\u5e36 (Tracking). \u50b3\u7d71\u7684\u904e\u5e36\u5fc5\u9808\u7d93\u904e\u985e\u6bd4\u7dda\u8def, \u96d6\u7136\u8072\u97f3\u4e0d\u932f, \u4f46\u662f\u7531\u65bc\u985e\u6bd4\u7dda\u8def\u6709\u5f88\u591a\u4e0d\u78ba\u5b9a\u6027, \u4f8b\u5982\u5916\u5728\u7684\u96dc\u8a0a, \u7dda\u6750, \u63a5\u982d, \u540c\u6b65 (Time Code) ... \u7b49\u8907\u96dc\u554f\u984c, \u6240\u4ee5\u7b97\u662f\u4e00\u500b\u5f88\u8f9b\u82e6\u53c8\u8907\u96dc\u7684\u904e\u7a0b, \u4f46\u662f\u537b\u662f\u6df7\u97f3\u524d\u5fc5\u6709\u7684\u6b65\u9a5f.","permalink":"/production/bouncing-tracks-tips"},{"id":"production/digital-gear-glossary","title":"\u6578\u4f4d\u5668\u6750\u3001\u97f3\u6a02\u88fd\u4f5c\u5c08\u6709\u540d\u8a5e\u5c0d\u7167\u8868","description":"\u73fe\u5728\u5e02\u9762\u4e0a\u8edf\u786c\u9ad4\u7522\u54c1\u773e\u591a\uff0c\u4f46\u662f\u5f88\u6176\u5e78\u7684\uff0c\u5927\u591a\u6578\u5ee0\u5546\u90fd\u6703\u63d0\u4f9b\u624b\u518a\u7d66\u4f7f\u7528\u8005\u4e0b\u8f09\u3002\u4f7f\u7528\u9019\u4e9b\u5668\u6750\u4e4b\u524d\uff08\u6216\u8005\u6e96\u5099\u6dfb\u8cfc\u65b0\u5668\u6750\u4e4b\u524d\uff09\uff0c\u6211\u5011\u90fd\u5df2\u7d93\u53ef\u4ee5\u5f9e\u624b\u518a\u77ad\u89e3\u5927\u90e8\u5206\u5668\u6750\u7684\u529f\u80fd\u3001\u898f\u683c\u7b49\u8cc7\u8a0a\u3002","permalink":"/production/digital-gear-glossary"},{"id":"production/music-terms-glossary","title":"\u6a02\u7406\u540d\u8a5e\u3001\u6f14\u594f\u8853\u8a9e\u5c08\u6709\u540d\u8a5e\u5c0d\u7167\u8868","description":"\u70ba\u4e86\u907f\u514d\u8aa4\u5c0e\uff0c\u6240\u4ee5\u5728\u6587\u7ae0\u4e2d\u63cf\u8ff0\u7684\u5404\u9805\u540d\u8a5e\u8cc7\u8a0a\u6211\u90fd\u6703\u5118\u91cf\u9644\u4e0a\u82f1\u6587\u539f\u6587\u7528\u5b57\uff0c\u7528\u5b57\u7684\u6a19\u6e96\u5118\u91cf\u4ee5\u5e38\u898b\u7684\u7528\u8a5e\u70ba\u6e96\u5247\u3002\u6211\u53c3\u8003\u7684\u66f8\u6709\u53f0\u7063\u51fa\u7248\u7684\u4e00\u4e9b\u4e2d\u6587\u6559\u6750 (\u5982\u5f81\u670d\u7434\u6d77)\uff0cHal Leonard \u7684 MI \u7cfb\u5217\u3001Wikipedia \u7684\u7dda\u4e0a\u6587\u7ae0\u3001\u5404\u5927\u8ad6\u58c7\u3001\u4e00\u4e9b\u7ffb\u8b6f\u66f8 ... \u7b49\u3002","permalink":"/production/music-terms-glossary"},{"id":"production/instrument-frequency-chart/index","title":"\u6a02\u5668\u97f3\u968e\u983b\u7387\u5c0d\u61c9\u8868","description":"\u5f88\u5be6\u7528\u7684\u8868\u683c\uff0c\u7de8\u66f2\u6642\u8981\u7279\u5225\u6ce8\u610f\u5404\u500b\u539f\u8072\u6a02\u5668\u7684\u97f3\u968e\u7bc4\u570d\uff0c\u6df7\u97f3\u6642\u8981\u770b\u983b\u7387\u7bc4\u570d\u3002","permalink":"/production/instrument-frequency-chart/"},{"id":"production/score-system-vs-producer","title":"\u6a02\u8b5c\u6392\u7248 (Music Score System) \u8207\u97f3\u6a02\u88fd\u4f5c (Music Producer System)","description":"\u9019\u6bb5\u6587\u5b57\u672c\u4f86\u662f\u653e\u5728 \u300e\u5982\u4f55\u628a MIDI \u505a\u5f97 \\"\u903c\u771f\\"\u300f\u88e1, \u4e0d\u904e\u56e0\u70ba\u6709\u670b\u53cb\u8ddf\u6211\u53cd\u61c9 Blog \u5f88\u591a\u6587\u7ae0\u7bc7\u5e45\u90fd\u592a\u9577, \u6240\u4ee5\u6211\u5c31\u60f3\u7a0d\u5fae\u8abf\u6574\u4e00\u4e0b\u7bc7\u5e45, \u65b9\u4fbf\u5927\u5bb6\u95b1\u8b80. \u9019\u662f\u7b2c\u4e00\u7bc7\u91cd\u65b0\u6574\u7406\u7684\u6587\u5b57, \u6b61\u8fce\u5927\u5bb6\u7d66\u6211\u5efa\u8b70.","permalink":"/production/score-system-vs-producer"},{"id":"production/recording-drums-basics","title":"\u9304\u9f13\u7684\u4e00\u4e9b\u57fa\u672c\u6982\u5ff5","description":"\u9f13\u7684\u9304\u97f3\u662f\u97f3\u6a02\u88fd\u4f5c\u4e2d\u7684\u4e00\u9805\u5927\u5de5\u7a0b\uff0c\u9700\u8981\u5177\u5099\u57fa\u790e\u77e5\u8b58\u3001\u6280\u8853\u8207\u8a2d\u5099\u3002\u672c\u6587\u6574\u7406\u9304\u9f13\u6240\u9700\u7684\u8a8d\u77e5\u8207\u6ce8\u610f\u4e8b\u9805\u3002\\n","permalink":"/production/recording-drums-basics"},{"id":"production/gear-costs-money","title":"\u9322\u63a8\u51fa\u4f86\u7684","description":"\u97f3\u6a02\u88fd\u4f5c\u54c1\u8cea\u597d\u58de\u7684\u56e0\u7d20\u5f88\u591a\uff0c\u4e00\u822c\u4f86\u8aaa\uff0c\u8a2d\u5099\u8ddf\u6280\u8853\u65b9\u9762\u7684\u56e0\u7d20 (\u4e0d\u8b1b\u7de8\u66f2\u3001\u6f14\u594f\u6280\u5de7) \u5e38\u898b\u7684\u6709\u4ee5\u4e0b\uff1a","permalink":"/production/gear-costs-money"},{"id":"production/keyboard-sound-overview","title":"\u9375\u76e4\u97f3\u8272\u6982\u8ff0","description":"\u95dc\u65bc\u97f3\u8272\u548c\u6f14\u594f\u624b\u6cd5\uff0c\u6211\u500b\u4eba\u7fd2\u6163\u4ee5 GM Group \u5207\u5165\u53bb\u8a8d\u8b58\uff0c\u57fa\u672c\u4e0a\u5404\u5927\u5ee0\u5408\u6210\u5668 (\u8a3b1) \u7684\u97f3\u8272\u5206\u985e\uff0c\u90fd\u53ef\u4ee5\u5f9e GM \u4f5c\u5206\u652f\uff0c\u540c\u6642\u5927\u90e8\u5206\u9ad8\u968e\u7434\u4e5f\u90fd\u6703\u652f\u63f4 GM\u3001GM2\uff0c\u6709\u4e9b\u4f34\u594f\u7434\u6703\u652f\u63f4 GM/GS/XG/GM2 \u7b49\u898f\u683c\u3002\u53e6\u5916\u5c31\u662f\u73fe\u5728\u8edf\u9ad4\u97f3\u6e90\u7684\u90e8\u4efd\uff0c\u7368\u7acb\u7684\u7522\u54c1\u4e5f\u5dee\u4e0d\u591a\u90fd\u662f\u540c\u6a23\u7684\u5206\u985e\u65b9\u5f0f\u3002","permalink":"/production/keyboard-sound-overview"},{"id":"production/pad-basics","title":"\u896f\u5e95 PAD \u7684\u57fa\u672c\u6982\u5ff5","description":"\u896f\u5e95 (Pad) \u662f\u97f3\u6a02\u88e1\u88fd\u9020\u6d41\u52d5\u611f\u3001\u547c\u5438\u611f\u7684\u9577\u97f3\u5143\u7d20\u3002\u4e86\u89e3 Pad \u7684\u985e\u578b\u8207\u7de8\u66f2\u6280\u5de7\uff0c\u53ef\u4ee5\u8b93\u97f3\u6a02\u66f4\u6709\u5c64\u6b21\u8207\u6c1b\u570d\u3002\\n","permalink":"/production/pad-basics"},{"id":"production/cc07-volume-cc11-expression","title":"CC#07 Main Volume \u548c CC#11 Expression","description":"CC#07 \u548c CC#11 \u662f MIDI Control \u8a0a\u865f\u88e1\u7d93\u5e38\u6703\u7528\u5230\u7684\u5169\u500b\u57fa\u672c\u63a7\u5236\u78bc, \u4ed6\u5011\u57fa\u672c\u7684\u529f\u80fd\u90fd\u662f\u7528\u4f86\u63a7\u5236 Track \u97f3\u91cf.","permalink":"/production/cc07-volume-cc11-expression"},{"id":"guitar/using-delay-effect","title":"Delay \u7684\u61c9\u7528","description":"Delay \u662f\u97f3\u6a02\u4e2d\u5f88\u5e38\u898b\u6548\u679c, \u5c24\u5176\u662f\u5409\u4ed6\u624b\u66f4\u662f\u5e38\u7528. \u5b83\u53ef\u4ee5\u6f64\u98fe\u8072\u97f3, \u5f48\u5206\u6563\u548c\u5f26\u6216\u8005 Solo \u52a0\u4e00\u9ede\u6703\u5f88\u6709 fu.","permalink":"/guitar/using-delay-effect"},{"id":"production/midi-sync-device-sequencer/index","title":"How to synchronize the MIDI messages between MIDI device and sequencer?","description":"\u4e0a\u500b\u6708\u8ddf\u670b\u53cb\u501f\u4e86\u4e00\u53f0 Roland DR-880 \u4f86\u73a9. \u9019\u53f0\u662f\u53f0\u5f88\u68d2\u7684 Drum Machine, \u4e0d\u7ba1\u662f\u7df4\u7fd2, \u505a\u5834, \u500b\u4eba\u89ba\u5f97\u90fd\u5f88\u65b9\u4fbf. \u4ed6\u7684\u9f13\u97f3\u8272\u6839\u64da\u5b98\u65b9\u7db2\u7ad9\u7684\u8cc7\u6599\u662f\u53d6\u81ea SRX \u7684\u97f3\u6e90, \u800c\u6211\u4e5f\u6709\u4e00\u5f35 SRX-01 \u9f13\u97f3\u6e90. \u5be6\u969b\u6e2c\u8a66\u904e, DR-880 \u7684 Rhythm \u9001\u7d66 SRX-01 \u5927\u90e8\u5206\u5728\u807d\u89ba\u4e0a\u662f\u52c9\u5f37 OK \u7684, \u4f46\u662f\u6709\u4e00\u4e9b Percussion (\u6253\u64ca\u6a02\u5668) \u90e8\u5206\u7684 Mapping \u9084\u662f\u8ddf SRX-01 \u4e0d\u592a\u4e00\u6a23, \u6240\u4ee5 detail \u7684\u90e8\u5206\u9084\u662f\u8981\u9760\u7de8\u66f2\u8005\u81ea\u5df1\u53bb\u4fee\u98fe. \u800c DR-880 \u9019\u53f0\u6a5f\u5668\u91cd\u9ede\u9084\u662f\u5728\u65bc\u7bc0\u594f\u7684\u90e8\u5206, \u4ed6\u5167\u5efa\u76f8\u7576\u591a\u8c50\u5bcc\u4e14\u5be6\u7528\u7684\u7bc0\u594f, \u56e0\u6b64\u8b93\u6211\u60f3\u628a\u4ed6\u64f7\u53d6\u51fa\u4f86\u8490\u85cf\u5230\u500b\u4eba\u7684\u7d20\u6750\u8cc7\u6599\u5eab\u88e1, \u65e5\u5f8c\u5728\u5275\u4f5c\u6642\u6709\u66f4\u591a\u7684\u6750\u6599\u53ef\u4ee5\u9078\u64c7.","permalink":"/production/midi-sync-device-sequencer/"},{"id":"production/loop-concepts-and-application-one-night-in-beijing/index","title":"Loop \u7684\u6982\u5ff5\u8207\u61c9\u7528\u5be6\u4f8b - One Night in \u5317\u4eac","description":"Loop \u5b57\u9762\u4e0a \u7684\u610f\u601d\u662f: \u5faa\u74b0, \u53cd\u8986, \u8ff4\u8def, \u6a61\u76ae\u5708 .... etc. \u5728\u97f3\u6a02\u88fd\u4f5c\u4e2d, \u4e2d\u6587\u53ef\u4ee5\u7ffb\u8b6f\u6210 \\"\u5faa\u74b0\u6a02\u53e5\\", \u6216\u8005 \\"\u53cd\u8986\u6bb5\u843d\\". \u7c21\u55ae\u8aaa\u5c31\u662f\u4e00\u6bb5\u4e00\u76f4\u53cd\u8986\u64ad\u653e\u7684 \\"\u6a02\u97f3\\".","permalink":"/production/loop-concepts-and-application-one-night-in-beijing/"},{"id":"production/mixer-interface-connection/index","title":"Mixer \u548c\u9304\u97f3\u754c\u9762\u7684\u9023\u63a5\u65b9\u5f0f","description":"\u4e5f\u662f\u7db2\u53cb\u63d0\u7684\u554f\u984c (ptt -> DigitalMusic \u7248). \u4e3b\u8981\u7684\u554f\u984c\u5c31\u662f\u81ea\u5b85\u9304\u97f3\u7684\u6642\u5019, \u662f\u5426\u9700\u8981\u7528\u5230 mixer \u9019\u6a23\u7684\u8a2d\u5099? \u5982\u679c\u9700\u8981\u90a3\u8981\u600e\u9ebc\u4e32\u63a5\u9304\u97f3\u754c\u9762\u8ddf mixer ?","permalink":"/production/mixer-interface-connection/"},{"id":"production/personal-monitor-system","title":"Personal Mixer / Monitor System (\u500b\u4eba\u76e3\u807d/\u7df4\u5718\u7cfb\u7d71)","description":"\u5728\u53f0\u7063\u73a9\u6a02\u5718\u4e00\u76f4\u662f\u593e\u7e2b\u4e2d\u6c42\u751f\u5b58\u7684, \u4e00\u500b\u6a19\u6e96\u6a02\u5718\u7de8\u5236\u7684\u6a02\u624b\u6240\u88fd\u9020\u7684 \\"\u6a02\u97f3\\" \u5728\u4e00\u822c\u7684\u516c\u5bd3\u88e1\u662f\u5f88\u96e3\u88ab\u5141\u8a31\u7684 (\u60f3\u8ddf\u8b66\u5bdf\u676f\u676f\u5f88\u719f\u7684\u8a71\u53ef\u4ee5\u8a66\u770b\u770b). \u9664\u975e\u6709\u76f8\u7576\u7684\u8ca1\u529b, \u88dd\u6f62\u81ea\u5df1\u7684\u7df4\u5718\u5ba4 / \u9304\u97f3\u5ba4, \u5426\u5247\u4e00\u822c\u6a02\u624b\u5011\u53ea\u80fd\u53bb\u79df\u7df4\u5718\u5ba4, \u7136\u5f8c\u5927\u5bb6\u53bb\u90a3\u908a\u7df4\u5718. \u4f46\u662f\u7df4\u5718\u5ba4\u7684\u8a2d\u5099 / \u72c0\u6cc1 / \u7a7a\u9593\u5927\u5c0f\u4e0d\u4e00, \xa0\u6240\u4ee5\u6bcf\u6b21\u7df4\u5718\u53ef\u80fd\u90fd\u6703\u8981\u91cd\u65b0\u9069\u61c9.","permalink":"/production/personal-monitor-system"}],"unlisted":false}}')}}]);